    /** Returns the maximum aggregate payload size accepted for one provisioned package. */ /** Descripción: Obtiene la información correspondiente a «getMaximumProvisioningPackageBytes» dentro de TransformationNativeRuntimeProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public long getMaximumProvisioningPackageBytes(){return maximumProvisioningPackageBytes;}
    /** Configures the bounded aggregate payload size for one provisioned package. */ /** Descripción: Actualiza el estado gestionado por TransformationNativeRuntimeProperties mediante la operación «setMaximumProvisioningPackageBytes». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setMaximumProvisioningPackageBytes(long value){maximumProvisioningPackageBytes=Math.max(1_048_576L,Math.min(8_589_934_592L,value));}
    /** Returns the maximum number of payload files accepted for one provisioned package. */ /** Descripción: Obtiene la información correspondiente a «getMaximumProvisioningFiles» dentro de TransformationNativeRuntimeProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public int getMaximumProvisioningFiles(){return maximumProvisioningFiles;}
    /** Configures the bounded number of payload files accepted for one provisioned package. */ /** Descripción: Actualiza el estado gestionado por TransformationNativeRuntimeProperties mediante la operación «setMaximumProvisioningFiles». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setMaximumProvisioningFiles(int value){maximumProvisioningFiles=Math.max(1,Math.min(100_000,value));}
    /** Returns the maximum trusted package-manifest size. */ /** Descripción: Obtiene la información correspondiente a «getMaximumProvisioningManifestBytes» dentro de TransformationNativeRuntimeProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public long getMaximumProvisioningManifestBytes(){return maximumProvisioningManifestBytes;}
    /** Configures the maximum trusted package-manifest size. */ /** Descripción: Actualiza el estado gestionado por TransformationNativeRuntimeProperties mediante la operación «setMaximumProvisioningManifestBytes». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setMaximumProvisioningManifestBytes(long value){maximumProvisioningManifestBytes=Math.max(1_024L,Math.min(4_194_304L,value));}
    /** Descripción: Obtiene la información correspondiente a «getAtlCommand» dentro de TransformationNativeRuntimeProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public List<String> getAtlCommand(){return List.copyOf(atlCommand);}
    /** Descripción: Actualiza el estado gestionado por TransformationNativeRuntimeProperties mediante la operación «setAtlCommand». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setAtlCommand(List<String> value){atlCommand=clean(value);}
    /** Descripción: Obtiene la información correspondiente a «getEtlCommand» dentro de TransformationNativeRuntimeProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public List<String> getEtlCommand(){return List.copyOf(etlCommand);}
    /** Descripción: Actualiza el estado gestionado por TransformationNativeRuntimeProperties mediante la operación «setEtlCommand». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setEtlCommand(List<String> value){etlCommand=clean(value);}
    /** Descripción: Obtiene la información correspondiente a «getAcceleoCommand» dentro de TransformationNativeRuntimeProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public List<String> getAcceleoCommand(){return List.copyOf(acceleoCommand);}
