    /** Descripción: Actualiza el estado gestionado por TransformationNativeRuntimeProperties mediante la operación «setJavaCommand». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setJavaCommand(List<String> value){javaCommand=clean(value);}
