    /** Descripción: Actualiza el estado gestionado por TransformationNativeRuntimeProperties mediante la operación «setXtendCommand». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setXtendCommand(List<String> value){xtendCommand=clean(value);}
